  --ui-font-heading: 'Hanken Grotesk', 'Hanken Grotesk Variable', 'Manrope', ui-sans-serif, system-ui, sans-serif;
  --ui-font-mono: 'SFMono-Regular', 'Cascadia Code', ui-monospace, monospace;
  --ui-tracking-body: 0;
  --ui-tracking-heading: -0.015em;
  --ui-leading-body: 1.55;
  --ui-leading-heading: 1.2;
  --ui-weight-body: 450;
  --ui-weight-heading: 600;
  --ui-weight-label: 550;
  --ui-shadow-control: 0 0 #0000;
  --ui-shadow-panel:
    0 1px 2px oklch(0.22 0.025 258 / 0.05), 0 8px 24px -12px oklch(0.22 0.025 258 / 0.1);
  --ui-shadow-overlay:
    0 2px 6px -2px oklch(0.22 0.025 258 / 0.08), 0 16px 40px -16px oklch(0.22 0.025 258 / 0.18);
  --ui-backdrop: oklch(0.2 0.01 258 / 0.24);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}

